const views={overlay:['OVERLAY VIEW','Compare datasets<br>on shared axes.','Compare peak positions, line shapes and signal amplitudes across selected curves. Control the display of complete series or individual datasets.','Measured fluorescence spectra from Sample G in CurveMole dark mode'],waterfall:['WATERFALL VIEW','Inspect trends<br>across a series.','Separate curves vertically to reveal patterns across a series. Follow peak shifts and shape changes without losing the context of the complete experiment.','Measured experimental fluorescence spectra in a dark-mode waterfall view'],fit:['INTERACTIVE FITTING','Inspect components<br>and fit residuals.','Inspect the fitted model alongside individual components and residuals. Review parameter values and uncertainties before exporting results.','Saved experimental multi-band fit, components and residuals in dark mode']};
const tabs=[...document.querySelectorAll('[data-view]')];function select(t){tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===t));b.tabIndex=b===t?0:-1});const key=t.dataset.view,v=views[key];document.getElementById('viewLabel').textContent=v[0];document.getElementById('viewTitle').innerHTML=v[1];document.getElementById('viewText').textContent=v[2];setScreenshot(document.getElementById('viewImage'),key);document.getElementById('viewImage').alt=v[3];document.getElementById('view-panel').setAttribute('aria-labelledby',t.id)}tabs.forEach((t,i)=>{t.addEventListener('click',()=>select(t));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%3;if(e.key==='ArrowLeft')n=(i+2)%3;if(e.key==='Home')n=0;if(e.key==='End')n=2;if(n!==undefined){e.preventDefault();tabs[n].focus();select(tabs[n])}})});

// Only the decorative signal field moves; scientific results stay fully visible.
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
const motionButton=document.getElementById('motionToggle');
let motionPaused=motionPreference.matches;
function applyMotion(){document.body.classList.toggle('motion-paused',motionPaused);motionButton.setAttribute('aria-pressed',String(motionPaused));motionButton.textContent=motionPaused?'Play background ▷':'Pause background Ⅱ'}
motionButton.addEventListener('click',()=>{motionPaused=!motionPaused;applyMotion()});
motionPreference.addEventListener('change',e=>{motionPaused=e.matches;applyMotion()});applyMotion();
const themeSlider=document.getElementById('themeSlider');
themeSlider.addEventListener('input',()=>{document.querySelector('.theme-comparison').style.setProperty('--split',themeSlider.value+'%');themeSlider.setAttribute('aria-valuetext',themeSlider.value+'% dark')});
const caseViews={
 notebook:['Keep the experimental story with the data.','The notebook records pressure cycles, repeat measurements, attenuation filters, saturation and alignment checks. The public copy retains the renamed laboratory log, with an English overview.','notebook-dark.png','Real CurveMole laboratory notebook with acquisition context and analysis decisions'],
 notes:['Record the assumptions behind a fit.','In Sample I, band centres were fixed using Sample G at matching pressures or extrapolated trends; only band areas were fitted. The original series note makes this assumption explicit. These centres are not independent estimates.','model-notes-dark.png','Actual series description documenting fixed band centres and fitted areas'],
 uncertainty:['Inspect intervals. Keep the warnings visible.','This saved fit includes 95% block-bootstrap intervals from 2,500 successful replicates, with no failed replicates. The table retains Attention flags. Residual-bootstrap analyses are also saved for 32 curves in the project.','uncertainty-dark.png','Actual saved block-bootstrap confidence intervals and diagnostic warnings'],
 trends:['Follow fitted quantities across an experiment.','Derived series in the project collect band-position trends across pressure changes. Compare these saved datasets and their fitted relationships alongside the source spectra, without losing the experimental context.','trends-dark.png','Real CurveMole view of derived band-position datasets and fitted trends']
};
function selectCase(button){const v=caseViews[button.dataset.case];caseTabs.forEach(t=>{t.setAttribute('aria-selected',String(t===button));t.tabIndex=t===button?0:-1});document.getElementById('caseHeading').textContent=v[0];document.getElementById('caseText').textContent=v[1];const image=document.getElementById('caseImage');image.src='assets/experimental/'+v[2];image.alt=v[3];image.removeAttribute('width');image.removeAttribute('height');document.getElementById('caseImageLink').href=image.src;document.getElementById('caseImageLink').setAttribute('aria-label','Open '+v[0]+' screenshot at full size');document.getElementById('case-panel').setAttribute('aria-labelledby',button.id)}
const caseTabs=[...document.querySelectorAll('[data-case]')];
caseTabs.forEach((t,i)=>{t.addEventListener('click',()=>selectCase(t));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%caseTabs.length;if(e.key==='ArrowLeft')n=(i+caseTabs.length-1)%caseTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=caseTabs.length-1;if(n!==undefined){e.preventDefault();caseTabs[n].focus();selectCase(caseTabs[n])}})});
// Reveal only when motion is allowed; all content remains readable without JS.
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');revealObserver.unobserve(entry.target)}}),{threshold:.08});
document.querySelectorAll('.section-top,.steps article,.open-grid article,.fit-modes article,.downloads a').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--delay',`${i%4*70}ms`);revealObserver.observe(el)});
// Suspend decorative traces when the opening section is out of view.
const heroSection=document.querySelector('.hero');
new IntersectionObserver(entries=>heroSection.classList.toggle('hero-inactive',!entries[0].isIntersecting)).observe(heroSection);
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));
